/**
 * The broker's bindings. `Env` (generated by `wrangler types`) only lists the
 * secrets when a `.dev.vars` exists, which CI has not, so they are declared
 * by hand here; `AUTH_KV` and the vars come from wrangler.jsonc either way.
 */
export interface AuthEnv extends Env {
  // From wrangler.jsonc, via the generated `Env`:
  //   AUTH_KV: burns redeemed authorization codes (one write per login).
  //   AUTH_HOST: the hostname the broker is served from (auth.lgtm.page).
  //   AUTH_PROVIDER_ORIGIN: rebases every GitHub/Google URL so e2e can stub
  //   the providers; empty in production.
  /** Secret: the GitHub OAuth App (callback `<issuer>/callback/github`). */
  GITHUB_CLIENT_ID: string;
  GITHUB_CLIENT_SECRET: string;
  /** Secret: the Google OAuth web client (redirect `<issuer>/callback/google`). */
  GOOGLE_CLIENT_ID: string;
  GOOGLE_CLIENT_SECRET: string;
  /** Secret: JSON array of private P-256 JWKs with `kid`; `pnpm auth:keygen`. */
  AUTH_SIGNING_KEYS: string;
  /** Secret: 32+ random bytes, base64. Rotating it rotates every client secret. */
  AUTH_MASTER_SECRET: string;
}

/** The secrets without which no auth route can work. */
export function missingAuthConfig(env: Partial<AuthEnv>): string[] {
  const required = [
    "AUTH_SIGNING_KEYS",
    "AUTH_MASTER_SECRET",
    "GITHUB_CLIENT_ID",
    "GITHUB_CLIENT_SECRET",
    "GOOGLE_CLIENT_ID",
    "GOOGLE_CLIENT_SECRET",
  ] as const;
  return required.filter((name) => !env[name]);
}
